1	import { Suspense } from 'react';
2	import Link from 'next/link';
3	import { getContent, visibleSorted } from '@/lib/cms/db';
4	import RichText from '@/components/RichText';
5	import { SkeletonHero } from '@/components/Skeleton';
6	import StatTile from '@/components/site/StatTile';
7	import RoleCard from '@/components/volunteers/RoleCard';
8	import StepItem from '@/components/volunteers/StepItem';
9	import VolunteerForm from '@/components/volunteers/VolunteerForm';
10	import { pageMetadata, readSeoOverrides } from '@/lib/seo';
11	import { CalendarPlus } from '@/components/icons';
12	
13	export const revalidate = 3600;
14	
15	export async function generateMetadata() {
16	  const content = await getContent();
17	  const o = readSeoOverrides(content, '/volunteers');
18	  const v = content?.volunteers || {};
19	  return pageMetadata({
20	    title: o.title || 'Volunteer — Third Eye Worldwide',
21	    description: o.description || v.heroSub || 'Help build free assistive technology. Translators, developers, narrators, and organisers always welcome.',
22	    path: '/volunteers',
23	    image: o.image,
24	    noindex: o.noindex,
25	  });
26	}
27	
28	export default function VolunteersPage() {
29	  return (
30	    <Suspense fallback={<SkeletonHero />}>
31	      <VolunteersPageContent />
32	    </Suspense>
33	  );
34	}
35	
36	async function VolunteersPageContent() {
37	  // DB hiccup → empty sections, not a 500. See app/page.tsx.
38	  let content = null;
39	  try {
40	    content = await getContent();
41	  } catch {
42	    // fall through to empty-content render
43	  }
44	  const v = content?.volunteers || {};
45	  const stats = visibleSorted(v.stats || []);
46	  const roles = visibleSorted(v.roles || []);
47	  const steps = visibleSorted(v.steps || []);
48	
49	  return (
50	    <>
51	      <div className="page-hero">
52	        <div className="page-hero-inner">
53	          <div className="section-eyebrow">{v.heroEyebrow || 'Volunteer'}</div>
54	          <RichText as="h1" html={v.heroTitle || 'Lend your skills.'} />
55	          {v.heroSub ? <p>{v.heroSub}</p> : null}
56	        </div>
57	      </div>
58	
59	      <section className="section">
60	        <div className="section-inner">
61	          {stats.length > 0 ? (
62	            <div className="vol-stat-grid">
63	              {stats.map((s, i) => <StatTile key={s.id || i} stat={s} />)}
64	            </div>
65	          ) : null}
66	
67	          <div className="section-heading left" style={{ maxWidth: 720 }}>
68	            <div className="section-eyebrow">Open Roles</div>
69	            <h2 className="section-title">Find a role that fits</h2>
70	            <p className="section-subtitle">
71	              {(v.rolesSubhead as string | undefined) ||
72	                'Every role is remote-friendly, self-paced, and paired with a mentor.'}
73	            </p>
74	          </div>
75	
76	          <div className="role-grid">
77	            {roles.length > 0
78	              ? roles.map((r) => <RoleCard key={r.id || r.title} role={r} />)
79	              : <p style={{ color: 'var(--fg-muted)' }}>No roles listed yet.</p>}
80	          </div>
81	        </div>
82	      </section>
83	
84	      <section className="section section-alt">
85	        <div className="section-inner">
86	          <div className="vol-split">
87	            <div>
88	              <div className="section-eyebrow">How It Works</div>
89	              <h2 className="vol-how-title">
90	                {(v.stepsHeading as string | undefined) ||
91	                  'From application to first contribution in under two weeks.'}
92	              </h2>
93	              <div className="vol-steps">
94	                {steps.map((s, i) => <StepItem key={s.id || i} step={s} />)}
95	              </div>
96	            </div>
97	            <VolunteerForm roles={roles} />
98	          </div>
99	        </div>
100	      </section>
101	
102	      <section className="cta-band">
103	        <div className="cta-inner">
104	          {(() => {
105	            const cta = (v.dropInCta || {}) as {
106	              heading?: string;
107	              body?: string;
108	              primaryLabel?: string;
109	              primaryHref?: string;
110	              secondaryLabel?: string;
111	              secondaryHref?: string;
112	            };
113	            const heading = cta.heading || 'Not sure where you fit?';
114	            const body = cta.body ||
115	              "Send an email — we'll set up a 20-minute call. No commitment, no script.";
116	            const primaryLabel = cta.primaryLabel || 'Email us';
117	            const primaryHref = cta.primaryHref ||
118	              'mailto:hello@thirdeyeworldwide.org?subject=Volunteer';
119	            const secondaryLabel = cta.secondaryLabel || 'Donate Instead';
120	            const secondaryHref = cta.secondaryHref || '/donate';
121	            return (
122	              <>
123	                <h2>{heading}</h2>
124	                <p>{body}</p>
125	                <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', justifyContent: 'center' }}>
126	                  <a href={primaryHref} className="btn-accent">
127	                    <CalendarPlus size="1em" aria-hidden="true" /> {primaryLabel}
128	                  </a>
129	                  <Link href={secondaryHref} className="btn-secondary">{secondaryLabel}</Link>
130	                </div>
131	              </>
132	            );
133	          })()}
134	        </div>
135	      </section>
136	    </>
137	  );
138	}
