1	'use client';
2	
3	import { useState } from 'react';
4	import { isValidEmail } from '@/lib/validators';
5	import { PaperPlaneTilt } from '@/components/icons';
6	
7	const HOURS_OPTIONS = ['1–2 hours', '3–5 hours', '6–10 hours', '10+ hours'];
8	const MESSAGE_MAX = 2000;
9	
10	/*
11	 * Volunteer application form. Submits to /api/submissions/volunteer.
12	 * `roles` is the CMS role list — checkbox labels come from role.title.
13	 */
14	import type { CmsItemMeta } from '@/lib/types';
15	
16	export interface RoleOpt extends CmsItemMeta {
17	  title?: string;
18	  desc?: string;
19	  icon?: string;
20	  tag1?: string;
21	  tag2?: string;
22	}
23	export interface VolunteerFormProps {
24	  roles: RoleOpt[];
25	}
26	
27	export default function VolunteerForm({ roles }: VolunteerFormProps) {
28	  const [first, setFirst] = useState('');
29	  const [last, setLast] = useState('');
30	  const [email, setEmail] = useState('');
31	  const [country, setCountry] = useState('');
32	  const [hours, setHours] = useState(HOURS_OPTIONS[0]);
33	  const [message, setMessage] = useState('');
34	  const [chosen, setChosen] = useState<Set<string>>(() => new Set<string>());
35	  // MED-1 honeypot — see DonateWidget for the explanation.
36	  const [website, setWebsite] = useState('');
37	  const [status, setStatus] = useState<{ text: string; error: boolean }>({
38	    text: "We accept applications from anywhere. We read every one personally — it may take us a few days to respond, especially if many come in at once.",
39	    error: false,
40	  });
41	  const [submitting, setSubmitting] = useState(false);
42	
43	  function toggleRole(title: string) {
44	    setChosen((prev) => {
45	      const next = new Set(prev);
46	      if (next.has(title)) next.delete(title);
47	      else next.add(title);
48	      return next;
49	    });
50	  }
51	
52	  async function submit() {
53	    if (!first.trim() || !last.trim()) {
54	      setStatus({ text: 'Please enter your name.', error: true });
55	      return;
56	    }
57	    if (!isValidEmail(email)) {
58	      setStatus({ text: 'Please enter a valid email.', error: true });
59	      return;
60	    }
61	    setSubmitting(true);
62	    setStatus({ text: 'Submitting…', error: false });
63	    try {
64	      const r = await fetch('/api/submissions/volunteer', {
65	        method: 'POST',
66	        headers: { 'Content-Type': 'application/json' },
67	        body: JSON.stringify({
68	          name: `${first} ${last}`.trim(),
69	          email,
70	          role: Array.from(chosen).join(', ') || null,
71	          skills: [country, hours].filter(Boolean).join(' · ') || null,
72	          message: message || null,
73	          website,
74	        }),
75	      });
76	      if (!r.ok) throw new Error('HTTP ' + r.status);
77	      setStatus({
78	        text: `Application received! We've sent a confirmation link to ${email}. Click it to confirm, and we'll be in touch within 48 hours.`,
79	        error: false,
80	      });
81	      // Reset every field on success.
82	      setFirst(''); setLast(''); setEmail('');
83	      setCountry(''); setMessage('');
84	      setChosen(new Set<string>());
85	      setHours(HOURS_OPTIONS[0]);
86	    } catch (e) {
87	      const msg = e instanceof Error ? e.message : String(e);
88	      setStatus({ text: `Could not submit: ${msg}`, error: true });
89	    } finally {
90	      setSubmitting(false);
91	    }
92	  }
93	
94	  return (
95	    <div className="vol-form">
96	      <h3>Apply to volunteer</h3>
97	      <p className="form-required-note">
98	        Fields marked <span aria-hidden="true" className="required-star">*</span>
99	        <span className="sr-only">with an asterisk</span> are required.
100	      </p>
101	      <div className="pay-row">
102	        <div className="pay-field">
103	          <label htmlFor="vol-first">
104	            First name <span aria-hidden="true" className="required-star">*</span>
105	          </label>
106	          <input id="vol-first" type="text" placeholder="Jane" value={first} onChange={(e) => setFirst(e.target.value)} aria-required="true" />
107	        </div>
108	        <div className="pay-field">
109	          <label htmlFor="vol-last">
110	            Last name <span aria-hidden="true" className="required-star">*</span>
111	          </label>
112	          <input id="vol-last" type="text" placeholder="Smith" value={last} onChange={(e) => setLast(e.target.value)} aria-required="true" />
113	        </div>
114	      </div>
115	      <div className="pay-field">
116	        <label htmlFor="vol-email">
117	          Email <span aria-hidden="true" className="required-star">*</span>
118	        </label>
119	        <input id="vol-email" type="email" placeholder="you@example.com" value={email} onChange={(e) => setEmail(e.target.value)} aria-required="true" />
120	      </div>
121	      {/* MED-1 honeypot. */}
122	      <input
123	        type="text"
124	        name="website"
125	        tabIndex={-1}
126	        autoComplete="off"
127	        aria-hidden="true"
128	        value={website}
129	        onChange={(e) => setWebsite(e.target.value)}
130	        style={{
131	          position: 'absolute',
132	          left: '-9999px',
133	          width: 1,
134	          height: 1,
135	          opacity: 0,
136	          pointerEvents: 'none',
137	        }}
138	      />
139	      <div className="pay-field">
140	        <label htmlFor="vol-country">Country / time zone</label>
141	        <input id="vol-country" type="text" placeholder="e.g. Lagos, WAT (UTC+1)" value={country} onChange={(e) => setCountry(e.target.value)} />
142	      </div>
143	      <div className="pay-field">
144	        <label>Preferred roles (pick all that apply)</label>
145	        <div className="checkbox-grid" style={{ marginTop: 4 }}>
146	          {roles.map((r: RoleOpt) => (
147	            <label key={r.title} className="cb-pill">
148	              <input
149	                type="checkbox"
150	                value={r.title || ''}
151	                checked={chosen.has(r.title || '')}
152	                onChange={() => toggleRole(r.title || '')}
153	              />{' '}
154	              {r.title || ''}
155	            </label>
156	          ))}
157	        </div>
158	      </div>
159	      <div className="pay-field">
160	        <label htmlFor="vol-hours">Hours per week you can commit</label>
161	        <select id="vol-hours" value={hours} onChange={(e) => setHours(e.target.value)}>
162	          {HOURS_OPTIONS.map((opt) => <option key={opt}>{opt}</option>)}
163	        </select>
164	      </div>
165	      <div className="pay-field">
166	        <label htmlFor="vol-message">Tell us about yourself (optional)</label>
167	        <textarea
168	          id="vol-message"
169	          rows={3}
170	          className="vol-textarea"
171	          maxLength={MESSAGE_MAX}
172	          placeholder="A few sentences about your interests and why TEWW…"
173	          value={message}
174	          onChange={(e) => setMessage(e.target.value)}
175	          aria-describedby="vol-message-counter"
176	        />
177	        <p
178	          id="vol-message-counter"
179	          className={`char-counter${message.length >= MESSAGE_MAX * 0.9 ? ' char-counter--warn' : ''}`}
180	          aria-live="polite"
181	        >
182	          {message.length} / {MESSAGE_MAX}
183	        </p>
184	      </div>
185	      <button
186	        type="button"
187	        className="btn-primary"
188	        style={{ width: '100%', justifyContent: 'center' }}
189	        onClick={submit}
190	        disabled={submitting}
191	        aria-busy={submitting}
192	      >
193	        {submitting
194	          ? <><span className="btn-spinner" aria-hidden="true" /> Submitting…</>
195	          : <><PaperPlaneTilt size="1em" aria-hidden="true" /> Submit Application</>}
196	      </button>
197	      <p
198	        aria-live="polite"
199	        className={`vol-status${status.error ? ' donate-status--error' : ''}`}
200	      >
201	        {status.text}
202	      </p>
203	    </div>
204	  );
205	}
