1	'use client';
2	
3	import { useState } from 'react';
4	import { isValidEmail } from '@/lib/validators';
5	import {
6	  CurrencyDollar,
7	  Gift,
8	  Heart,
9	  Info,
10	  Repeat,
11	  SealCheck,
12	} from '@/components/icons';
13	
14	/*
15	 * Donation widget. Owns every interactive piece of the /donate page:
16	 *   - monthly / one-time mode toggle
17	 *   - free-text amount input (donor decides what to give)
18	 *   - donor fields
19	 *   - submit to /api/submissions/donation
20	 *   - live status line
21	 *
22	 * Per the v2 content update, the previous tier grid (preset amounts
23	 * with "impact lines") is replaced with a single amount input. The
24	 * impact lines were aspirational — the org just incorporated and
25	 * doesn't yet have audited program-spend numbers to back them up.
26	 */
27	
28	type DonationMode = 'monthly' | 'once';
29	
30	function parseAmount(str: string | undefined): number {
31	  if (!str) return 0;
32	  const num = Number(String(str).replace(/[^0-9.]/g, ''));
33	  return Number.isNaN(num) ? 0 : num;
34	}
35	
36	export default function DonateWidget() {
37	  const [mode, setMode] = useState<DonationMode>('monthly');
38	  const [monthlyAmount, setMonthlyAmount] = useState('');
39	  const [onceAmount, setOnceAmount] = useState('');
40	  const [first, setFirst] = useState('');
41	  const [last, setLast] = useState('');
42	  const [email, setEmail] = useState('');
43	  const [note, setNote] = useState('');
44	  // MED-1 honeypot — humans never see this field (visually hidden,
45	  // taken out of the tab order, off the a11y tree). Bots that fill
46	  // every input blindly will fill this one too, and the API drops
47	  // any submission where it's non-empty.
48	  const [website, setWebsite] = useState('');
49	  const [status, setStatus] = useState<{ text: string; error: boolean }>({ text: '', error: false });
50	  const [submitting, setSubmitting] = useState(false);
51	
52	  async function submit(submitMode: DonationMode) {
53	    const raw = submitMode === 'monthly' ? monthlyAmount : onceAmount;
54	    const amount = parseAmount(raw);
55	
56	    if (!first.trim() || !last.trim()) {
57	      setStatus({ text: 'Please enter your name.', error: true });
58	      return;
59	    }
60	    if (!isValidEmail(email)) {
61	      setStatus({ text: 'Please enter a valid email.', error: true });
62	      return;
63	    }
64	    if (!amount || amount <= 0) {
65	      setStatus({ text: 'Please enter an amount.', error: true });
66	      return;
67	    }
68	    setSubmitting(true);
69	    setStatus({ text: 'Submitting…', error: false });
70	    try {
71	      const r = await fetch('/api/submissions/donation', {
72	        method: 'POST',
73	        headers: { 'Content-Type': 'application/json' },
74	        body: JSON.stringify({
75	          name: `${first} ${last}`.trim(),
76	          email,
77	          amount,
78	          mode: submitMode,
79	          note,
80	          website,
81	        }),
82	      });
83	      if (!r.ok) throw new Error('HTTP ' + r.status);
84	      // The form registers an INTENT to give. No card is charged on this
85	      // page — payment processing happens in a later step run by the
86	      // Third Eye team. Be explicit so donors don't think they're done.
87	      setStatus({
88	        text: `Thank you! We've sent a confirmation link to ${email}. Please click it to complete your submission — no payment is taken on this page.`,
89	        error: false,
90	      });
91	      // Reset every field so the form looks clean after success and a
92	      // donor doesn't accidentally re-submit the same payload twice.
93	      setFirst(''); setLast(''); setEmail(''); setNote('');
94	      setMonthlyAmount(''); setOnceAmount('');
95	    } catch (e) {
96	      const msg = e instanceof Error ? e.message : String(e);
97	      setStatus({ text: `Could not submit: ${msg}`, error: true });
98	    } finally {
99	      setSubmitting(false);
100	    }
101	  }
102	
103	  return (
104	    <div>
105	      <div className="donate-toggle" role="tablist" aria-label="Donation frequency">
106	        <button
107	          type="button"
108	          role="tab"
109	          className={mode === 'monthly' ? 'active' : ''}
110	          aria-selected={mode === 'monthly'}
111	          data-mode="monthly"
112	          onClick={() => setMode('monthly')}
113	        >
114	          <Repeat size="1em" aria-hidden="true" />{' '}
115	          <span className="t-label">Monthly</span>
116	        </button>
117	        <button
118	          type="button"
119	          role="tab"
120	          className={mode === 'once' ? 'active' : ''}
121	          aria-selected={mode === 'once'}
122	          data-mode="once"
123	          onClick={() => setMode('once')}
124	        >
125	          <CurrencyDollar size="1em" aria-hidden="true" />{' '}
126	          <span className="t-label">One-time</span>
127	        </button>
128	      </div>
129	
130	      {mode === 'monthly' ? (
131	        <div data-donate-mode="monthly">
132	          <div className="custom-amount custom-amount-solo">
133	            <label htmlFor="donate-amount-monthly" className="custom-amount-label">
134	              Choose your amount
135	            </label>
136	            <div className="custom-amount-input">
137	              <span className="cur">$</span>
138	              <input
139	                id="donate-amount-monthly"
140	                type="text"
141	                inputMode="decimal"
142	                pattern="[0-9]*\.?[0-9]*"
143	                maxLength={7}
144	                placeholder="Any amount"
145	                value={monthlyAmount}
146	                onChange={(e) => setMonthlyAmount(e.target.value)}
147	                aria-describedby="donate-amount-help-monthly"
148	              />
149	              <span className="custom-amount-suffix">/ month</span>
150	            </div>
151	            <p id="donate-amount-help-monthly" className="custom-amount-help">
152	              Whatever fits your budget. Every amount is welcome.
153	            </p>
154	          </div>
155	          <p className="donate-note">
156	            <SealCheck weight="fill" size="1em" style={{ color: 'var(--brand)' }} aria-hidden="true" />
157	            {' '}Monthly donors join the <strong>Circle of Access</strong> — quarterly impact
158	            reports, early product access, and two community events per year.
159	          </p>
160	          <button
161	            type="button"
162	            className="btn-accent donate-submit-btn"
163	            onClick={() => submit('monthly')}
164	            disabled={submitting}
165	            aria-busy={submitting}
166	          >
167	            {submitting
168	              ? <><span className="btn-spinner" aria-hidden="true" /> Submitting…</>
169	              : <><Heart weight="fill" size="1em" aria-hidden="true" /> Donate Monthly</>}
170	          </button>
171	        </div>
172	      ) : (
173	        <div data-donate-mode="once">
174	          <div className="custom-amount custom-amount-solo">
175	            <label htmlFor="donate-amount-once" className="custom-amount-label">
176	              Choose your amount
177	            </label>
178	            <div className="custom-amount-input">
179	              <span className="cur">$</span>
180	              <input
181	                id="donate-amount-once"
182	                type="text"
183	                inputMode="decimal"
184	                pattern="[0-9]*\.?[0-9]*"
185	                maxLength={7}
186	                placeholder="Any amount"
187	                value={onceAmount}
188	                onChange={(e) => setOnceAmount(e.target.value)}
189	                aria-describedby="donate-amount-help-once"
190	              />
191	              <span className="custom-amount-suffix">once</span>
192	            </div>
193	            <p id="donate-amount-help-once" className="custom-amount-help">
194	              Whatever fits your budget. Every amount is welcome.
195	            </p>
196	          </div>
197	          <p className="donate-note">
198	            <Gift weight="fill" size="1em" style={{ color: 'var(--accent)' }} aria-hidden="true" />
199	            {' '}One-time gifts of $500+ can be directed to a specific program. Your gift is
200	            tax-deductible in the US, UK, Canada, and India.
201	          </p>
202	          <button
203	            type="button"
204	            className="btn-primary donate-submit-btn"
205	            onClick={() => submit('once')}
206	            disabled={submitting}
207	            aria-busy={submitting}
208	          >
209	            {submitting
210	              ? <><span className="btn-spinner" aria-hidden="true" /> Submitting…</>
211	              : <><CurrencyDollar size="1em" aria-hidden="true" /> Give Once</>}
212	          </button>
213	        </div>
214	      )}
215	
216	      <div style={{ marginTop: 36 }}>
217	        <h3 className="donate-details-heading">Your details</h3>
