42	:root {
43	  --font-display: 'Literata', 'Literata Fallback', Georgia, serif;
44	  --font-body: 'Manrope', 'Manrope Fallback', sans-serif;
45	  --font-mono: 'DM Mono', 'Courier New', monospace;
46	  --radius-sm: 6px; --radius-md: 10px; --radius-lg: 16px; --radius-xl: 24px; --radius-full: 9999px;
47	  --space-1:.25rem;--space-2:.5rem;--space-3:.75rem;--space-4:1rem;--space-6:1.5rem;--space-8:2rem;--space-10:2.5rem;--space-12:3rem;--space-16:4rem;--space-20:5rem;--space-24:6rem;
48	  --maxw: 1280px;
49	
50	  /* Fluid display scale — headlines carry the editorial voice. */
51	  --text-hero: clamp(2.75rem, 1.9rem + 3.6vw, 5rem);
52	  --text-title: clamp(2rem, 1.55rem + 1.9vw, 3.25rem);
53	  --text-subtitle: clamp(1.35rem, 1.15rem + .8vw, 1.75rem);
54	
55	  /* Header height — used by the topnav and every sticky element that
56	     sits below it (subnav on /media /about /documents, the story-detail
57	     reading-progress bar, etc). Keeping it as a variable means future
58	     nav height changes don't need to hunt down hard-coded 68 px values
59	     across the stylesheet. */
60	  --header-height: 68px;
61	
62	  /*
63	   * CMS UI redesign — density + sidebar width vars (cms-redesign-plan.md §1).
64	   * Defaults match comfortable density. Overridden inside the CMS shell via
65	   * the `[data-density]` attribute on .adm-shell.
66	   */
67	  --row-y:    10px;
68	  --pad-card: 22px;
69	  --gap:      20px;
70	  --rail-w:   248px;
71	}
72	
73	/* CMS shell density toggle — overrides --row-y / --pad-card / --gap. */
74	[data-density="compact"]     { --row-y: 6px;  --pad-card: 16px; --gap: 14px; }
75	[data-density="comfortable"] { --row-y: 10px; --pad-card: 22px; --gap: 20px; }
