77	/* Day — warm bone paper, ink text, gold deepened for AA text duty. */
78	[data-theme="light"] {
79	  --bg:#f7f2e9;--bg-elevated:#fffdf8;--bg-subtle:#efe7d9;--bg-inverse:#16121e;
80	  --fg:#1c1826;--fg-muted:#5c5468;--fg-subtle:#7e7590;--fg-inverse:#f7f2e9;
81	  --border:#e2d8c6;--border-strong:#c9bca4;
82	  --brand:#8a5e12;--brand-hover:#6e4a0d;--brand-subtle:rgba(184,123,30,.12);
83	  --accent:#5b4bc4;--accent-hover:#483aa6;--accent-subtle:rgba(91,75,196,.10);
84	  --brand-fg:#fffdf8;--accent-fg:#fffdf8;
85	  --focus-ring:#5b4bc4;
86	  --shadow-sm:0 1px 3px rgba(28,24,38,.08),0 1px 2px rgba(28,24,38,.04);
87	  --shadow-md:0 4px 12px rgba(28,24,38,.10),0 2px 4px rgba(28,24,38,.06);
88	  --shadow-lg:0 10px 30px rgba(28,24,38,.12),0 4px 8px rgba(28,24,38,.06);
89	}
