91	/* Night — the default. Deep indigo dark lit by saffron gold. */
92	[data-theme="dark"] {
93	  --bg:#100e17;--bg-elevated:#171420;--bg-subtle:#1c1826;--bg-inverse:#f4efe6;
94	  --fg:#f4efe6;--fg-muted:#b3a9c0;--fg-subtle:#8d8399;--fg-inverse:#16121e;
95	  --border:#2a2438;--border-strong:#3a3350;
96	  --brand:#e8a33d;--brand-hover:#f2b856;--brand-subtle:rgba(232,163,61,.14);
97	  --accent:#9d8cff;--accent-hover:#b3a5ff;--accent-subtle:rgba(157,140,255,.14);
98	  --brand-fg:#16121e;--accent-fg:#16121e;
99	  --focus-ring:#f2b856;
100	  --shadow-sm:0 1px 3px rgba(0,0,0,.4);--shadow-md:0 4px 12px rgba(0,0,0,.5);--shadow-lg:0 10px 30px rgba(0,0,0,.6);
101	}
102	
103	/* High contrast — pure black/white, yellow interactive. AAA territory. */
104	[data-theme="high-contrast"] {
105	  --bg:#000;--bg-elevated:#0a0a0a;--bg-subtle:#111;--bg-inverse:#fff;
106	  --fg:#fff;--fg-muted:#e6e6e6;--fg-subtle:#bbb;--fg-inverse:#000;
107	  --border:#fff;--border-strong:#fff;
108	  --brand:#ffd700;--brand-hover:#ffe766;--brand-subtle:#332b00;
109	  --accent:#8ab4ff;--accent-hover:#b3ceff;--accent-subtle:#001a4d;
110	  --brand-fg:#000;--accent-fg:#000;
111	  --focus-ring:#ffff00;
112	  --shadow-sm:0 0 0 2px #fff;--shadow-md:0 0 0 2px #fff;--shadow-lg:0 0 0 3px #fff;
113	}
