115	[data-text-size="a"]{ font-size:16px; }
116	[data-text-size="a-plus"]{ font-size:18px; }
117	[data-text-size="a-plus-plus"]{ font-size:20px; }
118	
119	html {
120	  scroll-behavior: smooth;
121	  /* Anchor jumps (e.g. /about#team) land below the topnav AND the
122	     subnav, not behind them. Approximate the combined height: topnav
123	     (--header-height) + subnav (~48 px). */
124	  scroll-padding-top: calc(var(--header-height) + 56px);
125	}
126	body { font-family: var(--font-body); background: var(--bg); color: var(--fg); line-height: 1.65; -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; transition: background .25s ease, color .25s ease; min-height: 100vh; }
127	a { color: var(--brand); text-decoration: none; }
128	a:hover { color: var(--brand-hover); }
129	button { font: inherit; }
130	:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: 2px; border-radius: 4px; }
131	
