1	/* ── SECTION ────────────────────────────── */
2	.section { padding: var(--space-20) var(--space-8); }
3	.section-inner { max-width: var(--maxw); margin: 0 auto; }
4	.section-alt { background: var(--bg-subtle); }
5	.section-dark { background: var(--bg-inverse); color: var(--fg-inverse); }
6	.section-dark .section-title, .section-dark h2, .section-dark h3 { color: var(--fg-inverse); }
7	.section-dark .section-subtitle, .section-dark p { color: rgba(246,246,254,.75); }
8	[data-theme="dark"] .section-dark, [data-theme="high-contrast"] .section-dark { background: var(--bg-elevated); color: var(--fg); }
9	[data-theme="dark"] .section-dark .section-subtitle, [data-theme="dark"] .section-dark p { color: var(--fg-muted); }
10	
11	/* ── HERO (photo-led) ─────────────────────────── */
12	.hero {
13	  position: relative; overflow: hidden;
14	  min-height: 720px; height: calc(100vh - 68px); max-height: 860px;
15	  display: flex; align-items: flex-end;
16	  border-bottom: 1px solid var(--border);
17	  background: #0d0407;
18	}
19	/*
20	 * `--hero-image` is the URL the home page hero photo uses. Set it
21	 * via the inline style on `.hero-photo` (driven by CMS data).
22	 * Fallback below keeps the page intact if no CMS value is configured.
23	 */
24	.hero-photo {
25	  position: absolute; inset: 0; z-index: 0;
26	  --hero-image: url('https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=2400&q=80');
27	  background-image:
28	    linear-gradient(180deg, rgba(13,4,7,.18) 0%, rgba(13,4,7,.35) 40%, rgba(13,4,7,.88) 100%),
29	    linear-gradient(90deg, rgba(13,4,7,.6) 0%, rgba(13,4,7,0) 55%),
30	    var(--hero-image);
31	  background-size: cover; background-position: center 35%;
32	  filter: saturate(.95) contrast(1.05);
33	}
34	.hero-photo::after {
35	  /* warm tone wash to blend with brand orange */
36	  content:''; position:absolute; inset:0;
37	  background: linear-gradient(115deg, rgba(157,140,255,.16) 0%, rgba(0,0,0,0) 45%, rgba(232,163,61,.18) 100%);
38	  mix-blend-mode: screen;
39	}
40	/* Decorative low-opacity graphics layer */
41	.hero-graphics { position:absolute; inset:0; z-index:1; pointer-events:none; overflow:hidden; }
42	.hero-graphics svg.hg-eye {
43	  position:absolute; right:-80px; top:8%;
44	  width: 560px; height:auto; opacity:.10;
45	  color:#fff;
46	  animation: hgFloat 14s ease-in-out infinite;
47	  will-change: transform;
48	}
49	.hero-graphics svg.hg-rings {
50	  position:absolute; left: 6%; top: 18%;
51	  width: 380px; opacity:.14; color:#fff;
52	  animation: hgSpin 60s linear infinite;
53	  will-change: transform;
54	}
55	@media (prefers-reduced-motion: reduce) {
56	  .hero-graphics svg.hg-eye,
57	  .hero-graphics svg.hg-rings,
58	  .hero-graphics .hg-live .dot { animation: none; }
59	}
60	.hero-graphics .hg-dots {
61	  position:absolute; right: 8%; bottom: 26%;
62	  width: 220px; height: 220px; opacity:.35;
63	  background-image: radial-gradient(circle, rgba(255,255,255,.45) 1.4px, transparent 1.6px);
64	  background-size: 18px 18px;
65	  -webkit-mask-image: radial-gradient(circle at center, #000 40%, transparent 72%);
66	          mask-image: radial-gradient(circle at center, #000 40%, transparent 72%);
67	}
68	.hero-graphics .hg-line {
69	  position:absolute; left:0; right:0;
70	  height:1px; background: rgba(255,255,255,.08);
71	}
72	.hero-graphics .hg-line.l1 { top: 32%; }
73	.hero-graphics .hg-line.l2 { top: 62%; background: rgba(232,163,61,.22); }
74	.hero-graphics .hg-live {
75	  position:absolute; top: 28px; right: 32px;
76	  display:inline-flex; align-items:center; gap:8px;
77	  padding: 7px 12px 7px 10px; border-radius: 999px;
78	  background: rgba(255,255,255,.08); backdrop-filter: blur(10px);
79	  border: 1px solid rgba(255,255,255,.15);
80	  font-family: var(--font-display); font-size:.7rem; font-weight:600;
81	  letter-spacing:.12em; text-transform:uppercase; color:#fff;
82	}
83	.hero-graphics .hg-live .dot { width:6px; height:6px; border-radius:50%; background: var(--accent); box-shadow: 0 0 0 4px rgba(232,163,61,.25); animation: pulse 2s ease-in-out infinite; }
84	@keyframes hgFloat { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-18px); } }
85	@keyframes hgSpin { to { transform: rotate(360deg); } }
