/* Volunteers page — stats hairline row, how-it-works title, form extras */

/* Stats: gold Literata numerals between hairlines (spec §5). Overrides the
   generic .about-stat card look (06-about) inside the volunteers grid, and
   the base .vol-stat-grid (10-responsive) — so it carries its own
   responsive collapses too. */
.vol-stat-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
  margin-bottom: 72px;
  border-top: 1px solid color-mix(in oklab, var(--brand) 45%, var(--border));
  border-bottom: 1px solid var(--border);
}
.vol-stat-grid .about-stat {
  background: transparent; border: none; border-radius: 0; box-shadow: none;
  padding: 28px 24px;
  border-left: 1px solid var(--border);
}
.vol-stat-grid .about-stat:first-child { border-left: none; padding-left: 0; }
.vol-stat-grid .about-stat .n {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 1.5rem + 2vw, 3.4rem);
  font-weight: 600; letter-spacing: -.02em; line-height: 1;
  color: var(--brand); font-variant-numeric: tabular-nums;
}
.vol-stat-grid .about-stat .n em { color: var(--fg); font-style: italic; }
.vol-stat-grid .about-stat .l {
  font-family: var(--font-body); font-size: .85rem;
  color: var(--fg-muted); margin-top: 10px; line-height: 1.45;
}
@media (max-width: 820px) {
  .vol-stat-grid { grid-template-columns: 1fr 1fr; margin-bottom: 48px; }
  .vol-stat-grid .about-stat { padding: 22px 20px; }
  .vol-stat-grid .about-stat:nth-child(odd) { border-left: none; padding-left: 0; }
  .vol-stat-grid .about-stat:nth-child(n+3) { border-top: 1px solid var(--border); }
}

.vol-how-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 1.3rem + 1.8vw, 2.5rem);
  font-weight: 600;
  color: var(--fg);
  margin-bottom: 24px;
  letter-spacing: -.015em;
  line-height: 1.12;
  text-wrap: balance;
}
.vol-textarea {
  font-family: var(--font-body);
  font-size: .95rem;
  color: var(--fg);
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  padding: 11px 14px;
  outline: none;
  resize: none;
  transition: border-color .15s, box-shadow .15s;
}
.vol-textarea::placeholder { color: var(--fg-subtle); }
.vol-textarea:focus { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-subtle); }
.vol-status {
  font-size: .85rem;
  color: var(--fg-muted);
  margin-top: 12px;
  line-height: 1.5;
  text-align: center;
}

/* Donate page — widget extras, sidebar, transparency editorial */
.custom-amount-suffix {
  font-family: var(--font-display);
  font-size: .85rem;
  color: var(--fg-muted);
}
.donate-note {
  font-size: .88rem;
  color: var(--fg-muted);
  margin-bottom: 20px;
  line-height: 1.55;
}
.donate-note strong { color: var(--fg); }
.donate-submit-btn {
  width: 100%;
  justify-content: center;
  min-height: 48px;
  font-size: 1.05rem;
  padding: 16px;
}
.donate-details { margin-top: 36px; }
.donate-details-heading {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -.01em;
  color: var(--fg);
  margin-bottom: 16px;
}
.donate-status {
  margin-top: 10px;
  font-size: .9rem;
  line-height: 1.55;
  min-height: 1.4em;
}

.donate-sidebar { position: sticky; top: calc(var(--header-height) + 40px); }
.donate-impact-eyebrow {
  font-family: var(--font-body);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 10px;
}

/* Other ways to give — flat hairline block, gold-ruled like the impact list. */
.donate-other {
  background: transparent;
  border: none;
  border-top: 1px solid var(--brand);
  border-radius: 0;
  padding: 24px 0 0;
  margin-top: 40px;
}
.donate-other-eyebrow {
  font-family: var(--font-body);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 6px;
}
.donate-other-links {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.donate-other-links a {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
  font-family: var(--font-display);
  font-size: .95rem;
  font-weight: 500;
  text-decoration: none;
  transition: color .15s;
}
.donate-other-links a:last-child { border-bottom: none; }
.donate-other-links a svg { color: var(--brand); flex-shrink: 0; }
.donate-other-links a:hover { color: var(--brand); text-decoration: underline; }

/* Transparency — flat editorial columns under short gold rules (spec §5). */
.trust-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; }
.trust-item { position: relative; border-top: 1px solid var(--border); padding-top: 26px; }
.trust-item::before { content: ''; position: absolute; top: -1px; left: 0; width: 56px; height: 2px; background: var(--brand); }
.trust-item h3 {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-display); font-size: 1.25rem; font-weight: 600;
  letter-spacing: -.01em; color: var(--fg); margin-bottom: 10px;
}
.trust-item h3 svg { color: var(--brand); flex-shrink: 0; }
.trust-item p { font-size: .95rem; color: var(--fg-muted); line-height: 1.65; }
.trust-link {
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 44px; margin-top: 8px;
  font-family: var(--font-body); font-size: .9rem; font-weight: 700;
  color: var(--brand);
}
.trust-link:hover { color: var(--brand-hover); text-decoration: underline; }
@media (max-width: 980px) {
  .trust-grid { grid-template-columns: 1fr; gap: 32px; }
}

